alter table public.user_preferences
  add column endurance_goals jsonb not null default '[]'::jsonb
  check (jsonb_typeof(endurance_goals) = 'array' and jsonb_array_length(endurance_goals) <= 3 and pg_column_size(endurance_goals) <= 4096);

-- Sports d’endurance. Identifiants stables utilisés par le carnet et le coach.
on conflict (id) do nothing;

on conflict do nothing;
